        "topic": "微软推出“AI学生模拟器”",
        "progress": "微软研究院近日发布研究系统StudentSim，试图解决AI辅导工具开发中的一个关键难题：如何在没有大规模真人实验的情况下，判断一段讲解、提示或提问是否真正帮助学生进步。传统AI导师往往只看“答案是否正确”，但教学效果还取决于学生是否理解、能否纠正错误，以及不同学生是否需要不同解答支持。真实学习者研究能回答这些问题，却耗时、昂贵且难以规模化，难以支撑模型的快速迭代。微软为此推出StudentSim系统，基于公开、去标识化的学习者记录，为每位学生训练一个个性化“AI学生模拟器”。它不仅模拟学生如何独立作答，还模拟其在",
