        "topic": "AI 撬动量子计算：Anthropic 称 Claude 设计的量子电路超越顶尖现有方案",
        "progress": "IT之家 10 月 17 日消息，Anthropic 于 10 月 16 日发布研究称， 其 AI 模型 Claude 在几乎无需人工干预的情况下，针对 8 类量子计算任务，设计出比已发表最优电路更高效的方案。 IT之家援引博文介绍，量子计算机依靠量子比特运行，但当前设备通常仅有数百到数千个量子比特，且对热量、振动等环境噪声极为敏感。量子比特和运行时间都是稀缺资源，因此让量子计算走向实用的关键，是减少电路所需的量子比特数和量子门数量。 量子比特（qubit）是量子计算的“信息单元”：经典计算机用比特表示 0 或 1",
