        "topic": "英特尔、博通首席执行官警告：资金紧张或将成为人工智能最大瓶颈",
        "progress": "英特尔与博通两家企业的首席执行官发出警告，资金获取能力或将成为人工智能发展的一大主要约束。博通CEO陈福阳称，全行业都在加紧建设基础设施，支撑复杂度越来越高的AI大模型。相较于半导体、存储芯片或是电力短缺，融资问题可能会成为AI扩张更大的阻碍。“我认为最大的制约因素或许是资本。” 陈福阳周一于新加坡星展亚洲未来前瞻峰会上发言表示。英特尔CEO陈立武也对融资风险表达了相同的担忧。他指出，资本成本持续走高，同时市场也心存疑问：大举投入AI的企业，最终能否创造足够回报。（新浪财经）",
