        "topic": "2连板欢瑞世纪：公司AI短剧业务在上线数量、营收规模及成本效益转化方面尚未形成规模化效应",
        "progress": "36氪获悉，欢瑞世纪公告，公司连续两个交易日股票收盘价格涨幅偏离值累计超过20%，属于股票交易异常波动。截至目前，公司AI短剧业务在上线数量、营收规模及成本效益转化方面尚未形成规模化效应。2026年上半年，公司AI短剧业务营业收入占2026年半年度未经审计整体营业收入比例不足1%。公司AIGC相关业务收入占比低，对短期经营业绩不构成重大影响。",
